using Microsoft.AspNetCore.Mvc;using Sigov.Api.Contracts;using Sigov.Application.Abstractions;using Sigov.Application.Common;using Sigov.Application.Educacao.Avancada;
namespace Sigov.Api.Controllers;
[ApiController,Route("api/educacao/transporte")] public sealed class EducacaoTransporteEscolarController:EducacaoAvancadaControllerBase{readonly IEducacaoTransporteEscolarService _service;public EducacaoTransporteEscolarController(IEducacaoTransporteEscolarService service,ICurrentTenant tenant,ICurrentUser user):base(tenant,user)=>_service=service;
[HttpGet("dashboard")] public async Task<ActionResult<ApiResponse<object>>> Dashboard([FromQuery]EducacaoAvancadaFiltro filtro,CancellationToken ct) => OkResponse<object>(await _service.DashboardAsync(TenantId(),"educacao_transporte_rota",ct));
[HttpGet("rotas")] public async Task<ActionResult<ApiResponse<object>>> Listar1([FromQuery]EducacaoAvancadaFiltro filtro,CancellationToken ct) => OkResponse<object>(await _service.ListarAsync(TenantId(),"educacao_transporte_rota",filtro,ct));
[HttpPost("rotas")] public async Task<ActionResult<ApiResponse<long>>> Criar1(EducacaoAvancadaOperacaoRequest request,CancellationToken ct)=>OkResponse(await _service.CriarAsync(Contexto(),"educacao_transporte_rota",request,ct));
