[HttpPost("operacoes/{recurso}/{id:long}/status")] public async Task<ActionResult<ApiResponse<bool>>> Status(string recurso,long id,[FromQuery]string status,[FromQuery]string? justificativa,CancellationToken ct)=>OkResponse(await _service.AlterarStatusAsync(Contexto(),recurso,id,status,justificativa,ct));
[HttpGet("relatorios/resumo")] public async Task<ActionResult<ApiResponse<EducacaoAvancadaDashboardDto>>> Resumo(CancellationToken ct)=>OkResponse(await _service.DashboardAsync(TenantId(),"educacao_transporte_rota",ct));
